#!/usr/bin/env bash
# SPDX-License-Identifier: AGPL-3.0-only
# Regenerates the self-made RFC 3161 test fixtures in this directory with OpenSSL 3.
# Every key, certificate and token here is generated by this script for testing only:
# no real timestamp authority is involved. Private keys are written to a temporary
# directory and deleted; they are not committed. Running it again produces DIFFERENT bytes
# (new keys, new serials, new times), so the committed fixtures and their recorded
# OpenSSL verdicts (openssl-verdicts.txt) must be regenerated together.
#
# usage: tests/fixtures/evidence_tsa/gen.sh [outdir]   (default: this directory)
set -euo pipefail
OUT="${1:-$(cd "$(dirname "$0")" && pwd)}"
K="$(mktemp -d)"
trap 'rm -rf "$K"' EXIT
mkdir -p "$OUT/certs" "$OUT/tokens"
cd "$K"

cat > ext.cnf <<'X'
[req]
distinguished_name = dn
[dn]
[v3ca]
basicConstraints = critical,CA:TRUE
keyUsage = critical,keyCertSign,cRLSign
subjectKeyIdentifier = hash
[tsa]
basicConstraints = critical,CA:FALSE
keyUsage = critical,digitalSignature,nonRepudiation
extendedKeyUsage = critical,timeStamping
subjectKeyIdentifier = hash
authorityKeyIdentifier = keyid
[tsa_noncrit]
basicConstraints = critical,CA:FALSE
keyUsage = critical,digitalSignature
extendedKeyUsage = timeStamping
[tsa_wrongeku]
basicConstraints = critical,CA:FALSE
keyUsage = critical,digitalSignature
extendedKeyUsage = critical,serverAuth
X

# Minimal `openssl ca` setup so a certificate can be given explicit past dates.
ca_dates() { # issuer_cert issuer_key csr out ext start end sigopts...
  local ic=$1 ik=$2 csr=$3 out=$4 ext=$5 start=$6 end=$7; shift 7
  rm -rf cadb; mkdir cadb; : > cadb/index.txt; openssl rand -hex 8 > cadb/serial
  cat > ca.cnf <<C
[ca]
default_ca = d
[d]
database = cadb/index.txt
serial = cadb/serial
new_certs_dir = cadb
default_md = sha256
policy = p
unique_subject = no
copy_extensions = none
[p]
commonName = supplied
C
  openssl ca -batch -notext -config ca.cnf -cert "$ic" -keyfile "$ik" -in "$csr" -out "$out" \
    -extfile ext.cnf -extensions "$ext" -startdate "$start" -enddate "$end" "$@" 2>/dev/null
}

sign() { # issuer_cert issuer_key csr out ext [sigopts...]
  local ic=$1 ik=$2 csr=$3 out=$4 ext=$5; shift 5
  openssl x509 -req -in "$csr" -CA "$ic" -CAkey "$ik" -CAcreateserial -days 7300 \
    -extfile ext.cnf -extensions "$ext" -sha256 -out "$out" "$@" 2>/dev/null
}

csr() { openssl req -new -key "$1" -subj "/CN=$2" -out "$3"; }

# Chain R: RSA-2048 root -> RSA-2048 TSA (PKCS#1 v1.5 everywhere).
openssl genpkey -algorithm RSA -pkeyopt rsa_keygen_bits:2048 -out root-rsa.key 2>/dev/null
openssl req -x509 -new -key root-rsa.key -subj "/CN=Kshana Test Root RSA" -days 7300 \
  -sha256 -extensions v3ca -config ext.cnf \
  -out root-rsa.pem 2>/dev/null
openssl genpkey -algorithm RSA -pkeyopt rsa_keygen_bits:2048 -out tsa-rsa.key 2>/dev/null
csr tsa-rsa.key "Kshana Test TSA RSA" tsa-rsa.csr
sign root-rsa.pem root-rsa.key tsa-rsa.csr tsa-rsa.pem tsa

# A twin of the RSA TSA certificate: same key, issuer and serial number, different validity,
# so it is a different certificate that the token's ESS certificate hash does not name.
openssl x509 -req -in tsa-rsa.csr -CA root-rsa.pem -CAkey root-rsa.key -days 7000 \
  -set_serial "0x$(openssl x509 -in tsa-rsa.pem -noout -serial | cut -d= -f2)" \
  -extfile ext.cnf -extensions tsa -sha256 -out tsa-rsa-twin.pem 2>/dev/null

# Chain E: P-384 root -> P-256 intermediate -> P-256 TSA and P-384 TSA (ECDSA everywhere).
openssl genpkey -algorithm EC -pkeyopt ec_paramgen_curve:P-384 -out root-ec.key
openssl req -x509 -new -key root-ec.key -subj "/CN=Kshana Test Root EC" -days 7300 \
  -sha384 -extensions v3ca -config ext.cnf \
  -out root-ec.pem 2>/dev/null
openssl genpkey -algorithm EC -pkeyopt ec_paramgen_curve:P-256 -out int-ec.key
csr int-ec.key "Kshana Test Intermediate EC" int-ec.csr
openssl x509 -req -in int-ec.csr -CA root-ec.pem -CAkey root-ec.key -CAcreateserial -days 7300 \
  -extfile ext.cnf -extensions v3ca -sha384 -out int-ec.pem 2>/dev/null
openssl genpkey -algorithm EC -pkeyopt ec_paramgen_curve:P-256 -out tsa-ec256.key
csr tsa-ec256.key "Kshana Test TSA P-256" tsa-ec256.csr
sign int-ec.pem int-ec.key tsa-ec256.csr tsa-ec256.pem tsa
openssl genpkey -algorithm EC -pkeyopt ec_paramgen_curve:P-384 -out tsa-ec384.key
csr tsa-ec384.key "Kshana Test TSA P-384" tsa-ec384.csr
sign root-ec.pem root-ec.key tsa-ec384.csr tsa-ec384.pem tsa -sha384

# Chain P: RSA-PSS everywhere: root signs with PSS, TSA key is RSA and signs tokens with PSS
# (through `openssl cms -cades`, since `openssl ts -reply` cannot select PSS).
openssl genpkey -algorithm RSA -pkeyopt rsa_keygen_bits:2048 -out root-pss.key 2>/dev/null
openssl req -x509 -new -key root-pss.key -subj "/CN=Kshana Test Root RSA-PSS" -days 7300 \
  -sha256 -sigopt rsa_padding_mode:pss -sigopt rsa_pss_saltlen:32 -extensions v3ca \
  -config ext.cnf -out root-pss.pem 2>/dev/null
openssl genpkey -algorithm RSA -pkeyopt rsa_keygen_bits:2048 -out tsa-pss.key 2>/dev/null
csr tsa-pss.key "Kshana Test TSA RSA-PSS" tsa-pss.csr
sign root-pss.pem root-pss.key tsa-pss.csr tsa-pss.pem tsa -sigopt rsa_padding_mode:pss -sigopt rsa_pss_saltlen:32

# Bad TSA certificates under the RSA root.
openssl genpkey -algorithm RSA -pkeyopt rsa_keygen_bits:2048 -out tsa-bad.key 2>/dev/null
csr tsa-bad.key "Kshana Test TSA expired" tsa-exp.csr
ca_dates root-rsa.pem root-rsa.key tsa-exp.csr tsa-expired.pem tsa 20200101000000Z 20210101000000Z
csr tsa-bad.key "Kshana Test TSA EKU not critical" tsa-nc.csr
sign root-rsa.pem root-rsa.key tsa-nc.csr tsa-noncrit.pem tsa_noncrit
csr tsa-bad.key "Kshana Test TSA wrong EKU" tsa-we.csr
sign root-rsa.pem root-rsa.key tsa-we.csr tsa-wrongeku.pem tsa_wrongeku

printf 'Kshana RFC 3161 test message.\n' > "$OUT/data.txt"
printf 'A different message.\n' > "$OUT/other.txt"

tscnf() { # signer_cert key digest ess_alg extra_certs
  cat > ts.cnf <<T
[tsa_config1]
serial = $K/tsaserial
crypto_device = builtin
signer_cert = $1
signer_key = $2
signer_digest = $3
default_policy = 1.2.3.4.1
other_policies = 1.2.3.4.5
digests = sha256, sha384, sha512
accuracy = secs:1
ordering = no
tsa_name = no
ess_cert_id_chain = no
ess_cert_id_alg = $4
${5:+certs = $5}
T
  [ -f tsaserial ] || echo 01 > tsaserial
}

reply() { # name signer key digest ess_alg [extra_certs] [no-cert]
  local n=$1; tscnf "$K/$2" "$K/$3" "$4" "$5" "${6:+$K/$6}"
  local certflag=-cert; [ "${7:-}" = "no-cert" ] && certflag=
  openssl ts -query -data "$OUT/data.txt" -sha256 $certflag -out q.tsq
  openssl ts -reply -queryfile q.tsq -config ts.cnf -section tsa_config1 \
    -out "$OUT/tokens/$n.tsr" 2>/dev/null
}

reply rsa-sha256 tsa-rsa.pem tsa-rsa.key sha256 sha1
reply rsa-sha512-essv2 tsa-rsa.pem tsa-rsa.key sha512 sha256
reply ec256-chain tsa-ec256.pem tsa-ec256.key sha256 sha256 int-ec.pem
reply ec256-no-intermediate tsa-ec256.pem tsa-ec256.key sha256 sha256
reply ec384 tsa-ec384.pem tsa-ec384.key sha384 sha256
reply rsa-no-cert tsa-rsa.pem tsa-rsa.key sha256 sha1 "" no-cert
reply expired tsa-expired.pem tsa-bad.key sha256 sha256

# Tokens `openssl ts -reply` cannot make (it refuses a signer without a critical
# timeStamping EKU, and cannot select RSA-PSS): take the TSTInfo of a fresh reply and sign it
# again with `openssl cms -cades`, which adds the signingCertificateV2 attribute.
reply tmp tsa-rsa.pem tsa-rsa.key sha256 sha256
openssl ts -reply -in "$OUT/tokens/tmp.tsr" -token_out -out tok.der 2>/dev/null
openssl cms -verify -noverify -binary -inform DER -in tok.der -out tst.der 2>/dev/null
rm -f "$OUT/tokens/tmp.tsr"
cades() { # out signer key [keyopts...]
  local out=$1 c=$2 k=$3; shift 3
  openssl cms -sign -binary -nodetach -cades -nosmimecap -in tst.der \
    -econtent_type 1.2.840.113549.1.9.16.1.4 -signer "$c" -inkey "$k" -md sha256 "$@" \
    -outform DER -out "$OUT/tokens/$out"
}
cades pss.tst tsa-pss.pem tsa-pss.key -keyopt rsa_padding_mode:pss -keyopt rsa_pss_saltlen:32
cades eku-noncritical.tst tsa-noncrit.pem tsa-bad.key
cades eku-wrong.tst tsa-wrongeku.pem tsa-bad.key
cades rsa-cades.tst tsa-rsa.pem tsa-rsa.key

# Tampered variants of good tokens, each a single changed byte.
flip() { # in out offset(negative = from end) xor
  python3 -I -c 'import sys
d=bytearray(open(sys.argv[1],"rb").read()); o=int(sys.argv[3])
d[o]^=int(sys.argv[4],16); open(sys.argv[2],"wb").write(d)' "$@"
}
# The signature value is the last element of the token: flip its last byte.
flip "$OUT/tokens/rsa-sha256.tsr" "$OUT/tokens/rsa-sha256-sigflip.tsr" -1 01
flip "$OUT/tokens/ec256-chain.tsr" "$OUT/tokens/ec256-chain-sigflip.tsr" -1 01
flip "$OUT/tokens/pss.tst" "$OUT/tokens/pss-sigflip.tst" -1 01
# Change the TSTInfo policy 1.2.3.4.1 to 1.2.3.4.0 (bytes 06 03 2a 03 04 01 in eContent):
# the messageDigest attribute no longer matches the TSTInfo.
pol() { python3 -I -c 'import sys
d=bytearray(open(sys.argv[1],"rb").read()); i=d.index(bytes.fromhex("06042a030401"))
d[i+5]^=1; open(sys.argv[2],"wb").write(d)' "$@"; }
pol "$OUT/tokens/rsa-sha256.tsr" "$OUT/tokens/rsa-sha256-tstinfo-changed.tsr"
pol "$OUT/tokens/ec384.tsr" "$OUT/tokens/ec384-tstinfo-changed.tsr"

# Intermediate certificate's signature changed inside the token (the ESS hash names only the
# TSA certificate, so only the chain is broken).
splice() { # token cert_pem out mode(flip-last|replace:<pem>)
  python3 -I -c 'import sys,subprocess
d=bytearray(open(sys.argv[1],"rb").read())
der=lambda p: subprocess.run(["openssl","x509","-in",p,"-outform","DER"],capture_output=True,check=True).stdout
c=der(sys.argv[2]); i=d.index(c)
if sys.argv[4]=="flip-last": d[i+len(c)-1]^=1
else:
    r=der(sys.argv[4].split(":",1)[1]); assert len(r)==len(c), "twin length differs"; d[i:i+len(c)]=r
open(sys.argv[3],"wb").write(d)' "$@"
}
splice "$OUT/tokens/ec256-chain.tsr" int-ec.pem "$OUT/tokens/ec256-chain-intsigflip.tsr" flip-last
# The TSA certificate replaced by its twin: the signature still verifies with the same key and
# the chain is valid, but the ESS signing-certificate hash no longer names the certificate.
splice "$OUT/tokens/rsa-sha256.tsr" tsa-rsa.pem "$OUT/tokens/rsa-sha256-ess-twin.tsr" replace:tsa-rsa-twin.pem

for c in root-rsa root-ec int-ec root-pss tsa-rsa tsa-ec256; do cp "$c.pem" "$OUT/certs/"; done
echo "fixtures written to $OUT"
